/** The map position stored for one location: latitude, longitude and where it came from (google, places, dataforseo, tracker, or manual when someone set it by hand). lat, lng and source are null until a source has placed the location. Read only. Needs location:read. */
export async function locations_center_get(input: unknown = {}) {
  return runAction("locations.center.get", input);
}

/** Set a location's map position by hand (latitude -90 to 90, longitude -180 to 180). The position is marked manual and automatic lookups never replace it, even when the address changes, until locations.center.clearManual. Does not write to Google. Needs workspace:manage (owner, admin). */
export async function locations_center_set(input: unknown = {}) {
  return runAction("locations.center.set", input);
}

/** Go back to automatic map positions: removes a hand-set position and queues a new lookup (Google, Places, DataForSEO, then the rank tracker). Does nothing when the position is not manual. Does not write to Google. Needs workspace:manage (owner, admin). */
export async function locations_center_clearManual(input: unknown = {}) {
  return runAction("locations.center.clearManual", input);
}

/** List your own write proposals, newest first, with status (pending, applied, expired, cancelled, failed), expiry, the preview that was shown and the name of the token that made each. Over MCP: this token's proposals. In the web app: every token of the signed-in person. status filters before limit; expired includes pending proposals past their expiry. A failed proposal's error reads CODE: message. */
export async function mcp_proposals_list(input: unknown = {}) {
  return runAction("mcp.proposals.list", input);
}

/** Apply a proposal returned by a write tool (phase 2 of propose -> check -> approve -> publish). Single use: it re-checks that the proposal is still pending and unexpired, was created by this API token and user (or, in the web app, that the signed-in person owns the token that created it; then the token must not be revoked and its read-only or client limits still apply), that its stored input is intact, that you are still authorized, and that the policy findings still do not block it; then it runs the write exactly as if you had called the tool, audit rows included. A second apply is CONFLICT. Returns the write's own result. */
export async function mcp_proposals_apply(input: unknown = {}) {
  return runAction("mcp.proposals.apply", input);
}

/** Cancel a pending proposal so it can no longer be applied. Only the API token that created it, or its owner signed in to the web app, can cancel it. */
export async function mcp_proposals_cancel(input: unknown = {}) {
  return runAction("mcp.proposals.cancel", input);
}

/** Scheduled background jobs on this server (schedule in UTC, last run, result ok/failed/running/never, next run, late when two scheduled runs in a row were missed; error text for owners and admins only) and, for the locations you can see (sorted by name, up to 500), when reviews were last synced, the newest sync attempt and its reason code, the last performance snapshot date and when a profile change was last found. Never calls Google. */
export async function system_status(input: unknown = {}) {
  return runAction("system.status", input);
}

/** System health for the whole server (platform administrators only; everyone else gets FORBIDDEN): the worker's last heartbeat and whether it is stale, how alerts are delivered (email to ALERT_EMAIL, or only written to the log), the most recent distinct server errors with how often each was seen (messages are stripped of secrets and personal data), and Google Business API calls per day and method against the 300 requests per minute limit. Read-only, never calls Google. */
export async function monitoring_overview(input: unknown = {}) {
  return runAction("monitoring.overview", input);
}

/** Search locations (name, title, address), review text (and the reviewer's name unless anonymous) and post text in one call, for the ⌘K box. q is matched literally, case-insensitively. Reviews and posts are only searched from 3 characters (locations from 1), so a short q returns locations only. Returns at most limitPerKind (1-10, default 5) of each kind, newest first for reviews and posts. Scope with workspaceId, groupId or locationIds, the same as reviews.list; client roles only see their own workspaces. Reviews are active locations only. Internal notes and assignments are never searched or returned. */
export async function search_everything(input: unknown = {}) {
  return runAction("search.everything", input);
}

/** Draft text with AI for a client. purpose 'reply' (a reply to a review: sourceText is the review text; optional rating and reviewerName) or 'post' (a Google post: sourceText is the topic). The draft uses the client's brand voice (tone, banned words, sign-off, language), is metered (tokens, model, cost), and then runs through the same guardrails as replies and posts for the client's profile. status 'ok' returns the draft (warningRuleIds lists non-blocking findings); status 'blocked' returns blockedRuleIds and NO text. The call is refused before it is made when it would exceed the platform's or the client's monthly AI limit, and fails with NOT_CONFIGURED when this server has no AI key. A draft is only a proposal: it still goes through approval. Needs review:draft (owner, admin, manager). */
export async function ai_draftText(input: unknown = {}) {
  return runAction("ai.draftText", input);
}

/** Draft a reply to one review with AI. Reads the review itself (text, star rating, reviewer first name only, location, the client's brand voice and a few of its reply templates as style examples) and writes in the review's language unless the client's brand voice sets one (language is a hint you may pass). A 1-2 star review gets an apology and an offer to take it offline, with no admission of fault. The draft is metered, em dashes are replaced, and it runs through the same guardrails as a typed reply for this location (including the duplicate check against its recent replies). status 'ok' returns the draft text (warningRuleIds lists non-blocking findings, for example wording the writing style bans); status 'blocked' returns blockedRuleIds and NO text. Refused with AI_BUDGET_EXCEEDED over the monthly cap, NOT_CONFIGURED when this server has no AI key. Nothing is saved: put the text in reviewReplies.createDraft, then reviewReplies.submit. Needs review:draft (owner, admin, manager). */
export async function ai_draftReply(input: unknown = {}) {
  return runAction("ai.draftReply", input);
}

/** Draft replies with AI for up to 20 reviews and put each into the approval queue. One AI call per review, one after another. For each review: drafted (saved and submitted; replyStatus pending_approval, or approved if the client's star rule approves it), blocked (a guardrail blocked the draft; blockedRuleIds; nothing saved), refused (over the monthly cap: the run stops there and the rest are not_attempted), skipped (the review already has a reply or a draft, or is not found or not allowed), failed (the AI call failed). Warnings (for example banned wording) do not stop a draft: they are stored on it and a person sees them in approval. If the client's star rule would auto-approve the draft, a draft with warnings stays a draft instead (replyStatus draft) until a person reads it. Each draft goes through the same metering, guardrails and audit as ai.draftReply. NOT_CONFIGURED when this server has no AI key. Needs review:draft (owner, admin, manager). */
export async function ai_draftReplies(input: unknown = {}) {
  return runAction("ai.draftReplies", input);
}

/** Draft the business description for a location with AI. At most 750 characters (a longer answer is retried once, then cut at a sentence end), plain text, no links, in the client's brand voice and the writing style. The location's top Google search keywords from the stored Performance data are offered to the model as context; keywordsIncluded says which of them the draft happens to use (a hint, never forced). Optional facts the caller already has: categories, services and currentDescription (to improve it). status 'ok' returns the draft; status 'blocked' returns blockedRuleIds and NO text. The draft is only returned: nothing is saved, so it still goes through profile.preview, profile.propose and approval. Metered and capped like ai.draftText; the text sent to the model is never logged. Needs profile:edit and review:draft (owner, admin, manager). */
export async function ai_draftBusinessDescription(input: unknown = {}) {
  return runAction("ai.draftBusinessDescription", input);
}

/** Draft the description of one service for a location with AI. At most 1000 characters (a longer answer is retried once, then cut at a sentence end), plain text, no links, in the client's brand voice and the writing style. serviceName is required; categoryName and currentDescription are optional context. status 'ok' returns the draft; status 'blocked' returns blockedRuleIds and NO text. The draft is only returned: nothing is saved, so it still goes through profile.preview, profile.propose and approval. Metered and capped like ai.draftText; the text sent to the model is never logged. Needs profile:edit and review:draft (owner, admin, manager). */
export async function ai_draftServiceDescription(input: unknown = {}) {
  return runAction("ai.draftServiceDescription", input);
}

/** Suggest 5 short Google post ideas for one location with AI, drawn from its services, a general theme of its recent positive reviews (never a quote or a reviewer's name; none at all for healthcare clients) and the occasions coming up in the next 60 days for the client's market (US, AU or IN, from the client's time zone). One AI call, metered and audited like ai.draftText. status 'ok' returns ideas; status 'blocked' returns blockedRuleIds and no ideas. Pick one, then call ai.draftPost with it. Refused with AI_BUDGET_EXCEEDED over the monthly cap, NOT_CONFIGURED when this server has no AI key. Nothing is saved. Needs review:draft (owner, admin, manager). */
export async function ai_postIdeas(input: unknown = {}) {
  return runAction("ai.postIdeas", input);
}

/** Write one Standard Google post for one location with AI, ready to drop into the composer. idea (optional, up to 300 characters) is one of the ai.postIdeas lines; without it the AI picks from the location's services, a general theme of its recent positive reviews and the next 60 days of occasions. Aims at about 600 characters (the post limit is 1500). Metered, em dashes removed, and run through the post guardrails for that location. status 'ok' returns the text (warningRuleIds lists non-blocking findings such as banned wording); status 'blocked' returns blockedRuleIds and NO text. Nothing is saved: put the text in posts.createDraft, then posts.submit. Needs review:draft (owner, admin, manager). */
export async function ai_draftPost(input: unknown = {}) {
  return runAction("ai.draftPost", input);
}

/** Write a different Standard post for each of up to 20 locations of one client with AI and put each into the approval queue as its own post (one location per post). One AI call per location, one after another, each committed on its own: a failure on one location never undoes the others. Each text names the location or its city and opens differently from the posts already written in the run. idea is optional (see ai.draftPost). For each location: drafted (saved and submitted; postStatus pending_approval, with any warnings stored on the post for the approver to read), blocked (a guardrail blocked the text; nothing saved), refused (over the monthly cap: the run stops there and the rest are not_attempted), skipped (not an active location of this client), failed (the AI call or the save failed). Posts always need a person to approve them; nothing is scheduled or sent. Same metering, guardrails and audit as ai.draftPost. NOT_CONFIGURED when this server has no AI key. Needs review:draft (owner, admin, manager). */
export async function ai_draftPostVariants(input: unknown = {}) {
  return runAction("ai.draftPostVariants", input);
}

/** A client's AI brand voice: tone, bannedWords, signOff and language (empty language = the language of the source text). A client that was never set up returns empty values. Needs review:read. */
export async function aiVoice_get(input: unknown = {}) {
  return runAction("aiVoice.get", input);
}

/** Set a client's AI brand voice; only the fields you pass change. tone: up to 200 characters (for example 'warm, plain, no jargon'). bannedWords: up to 50 words or phrases the drafts must not use. signOff: up to 200 characters, added at the end of every draft. language: up to 40 characters, a language name or code; empty means the language of the source text. These feed the AI prompt; the guardrails still check every output. Needs review:draft (owner, admin, manager). */
export async function aiVoice_update(input: unknown = {}) {
  return runAction("aiVoice.update", input);
}

/** Set (or clear with null) one client's monthly AI spend cap in USD. A draft that would take the client over it is refused before the model is called. The platform-wide cap (AI_MONTHLY_BUDGET_USD) applies on top. The month is the UTC calendar month. Needs review:configure (owner, admin). */
export async function aiUsage_setClientCap(input: unknown = {}) {
  return runAction("aiUsage.setClientCap", input);
}

/** This month's (UTC) AI spend per client the caller can see, with each client's cap (null = none), and whether AI is set up on this server. platform (spend and cap across all organizations) is returned only to platform admins, otherwise null. Needs review:configure (owner, admin). */
export async function aiUsage_get(input: unknown = {}) {
  return runAction("aiUsage.get", input);
}

/** Classify a client's reviews by topic and sentiment with AI (topics: staff, wait_time, price_value, cleanliness, results_quality, communication, booking, location_parking, other; sentiment positive, negative or mixed, per topic and overall). Takes reviews that have text and no current classification, newest first, up to 200 per run (remaining says how many still wait; run again). Several reviews go in one AI call. A review that was already classified and has not been edited is never classified or paid for again; an edited review is classified again. A review the AI answered badly twice is marked unclassified and is retried by the next run. Metered and capped like drafts: stopped 'cap' means a monthly AI limit was reached (what was done is kept), 'error' means the AI service failed. Only topics and sentiment are stored, never the review text, and review text is never logged. Optional locationIds narrows to those locations of the client. NOT_CONFIGURED when this server has no AI key. Needs review:draft (owner, admin, manager). */
export async function reviews_classifyTopics(input: unknown = {}) {
  return runAction("reviews.classifyTopics", input);
}

/** Review topics over the last 12 weeks (UTC weeks starting Monday, by the review's create time), from reviews already classified by reviews.classifyTopics (nothing here calls AI). For the whole scope: per topic the number of mentions (total) and how many were positive, negative or mixed, with positiveShare and negativeShare (0 to 1, null when no mentions), and the same counts for each week. Per location: the same per-topic counts over the window. Also classifiedReviews and the overall sentiment counts. Reviews edited since they were classified are left out until classified again. Filters: workspaceId, locationIds, groupId. Active locations in the caller's clients only. Counts only: no review text or reviewer names. truncated is true when more than 50000 reviews matched. */
export async function reviews_topicTrends(input: unknown = {}) {
  return runAction("reviews.topicTrends", input);
}

/** Turn the daily automatic classification of a client's new reviews by topic and sentiment on or off. Off by default, because every classification uses the client's AI allowance. Needs review:configure (owner, admin). */
export async function reviewTopics_setAuto(input: unknown = {}) {
  return runAction("reviewTopics.setAuto", input);
}

/** Where a client's review classification stands: whether the daily automatic classification is on (autoClassify), whether AI is set up on this server (aiOn), how many reviews are classified (classified), could not be classified (unclassified) and still wait (pending: with text and no current classification, including unclassified ones a manual run would retry). Counts only. Needs review:read. */
export async function reviewTopics_status(input: unknown = {}) {
  return runAction("reviewTopics.status", input);
}
